package com.google.gson.stream;

import com.google.gson.internal.JsonReaderInternalAccess;
import com.google.gson.internal.bind.JsonTreeReader;
import java.io.*;
import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonReader_nextInt_TriageGen0Test {

    @Test
    public void testNextInt_FromPeekedLong() throws IOException {
        // Simulates the path where p == PEEKED_LONG
        // Since we cannot easily inject internal state into JsonReader, 
        // we provide a valid integer in JSON format which the reader will parse.
        // Note: To specifically hit the PEEKED_LONG branch in a real scenario, 
        // one would need to use reflection or a subclass, but for standard unit testing 
        // of the public API, we test the functional outcomes.
        String json = "123";
        JsonReader reader = new JsonReader(new StringReader(json));
        assertEquals(123, reader.nextInt());
    }

    @Test
    public void testNextInt_FromPeekedLong_PrecisionLoss() throws IOException {
        // Testing the branch: if (peekedLong != result) throw NumberFormatException
        // We use a value larger than Integer.MAX_VALUE
        String json = "2147483648"; 
        JsonReader reader = new JsonReader(new StringReader(json));
        try {
            reader.nextInt();
            org.junit.Assert.fail("Expected NumberFormatException due to precision loss");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testNextInt_FromPeekedNumber() throws IOException {
        // Testing the path: p == PEEKED_NUMBER
        String json = "456";
        JsonReader reader = new JsonReader(new StringReader(json));
        assertEquals(456, reader.nextInt());
    }

    @Test
    public void testNextInt_FromPeekedDouble() throws IOException {
        // Testing the path: p == PEEKED_NUMBER -> Double.parseDouble -> (int) cast
        // This covers the branch where it's parsed as a double first
        String json = "123.0";
        JsonReader reader = new JsonReader(new StringReader(json));
        assertEquals(123, reader.nextInt());
    }

    @Test
    public void testNextInt_FromPeekedDouble_PrecisionLoss() throws IOException {
        // Testing: if (result != asDouble) throw NumberFormatException
        String json = "123.45";
        JsonReader reader = new JsonReader(new StringReader(json));
        try {
            reader.nextInt();
            org.junit.Assert.fail("Expected NumberFormatException due to decimal part");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testNextInt_FromPeekedDouble_InvalidFormat() throws IOException {
        // Testing: double asDouble = Double.parseDouble(peekedString); (don't catch)
        String json = "not_a_number";
        JsonReader reader = new JsonReader(new StringReader(json));
        try {
            reader.nextInt();
            org.junit.Assert.fail("Expected NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testNextInt_FromPeekedSingleQuoted() throws IOException {
        // Testing: p == PEEKED_SINGLE_QUOTED
        // Note: GSON is usually strict, but if lenient is set or via specific input
        // Since we can't easily force the internal 'p' to PEEKED_SINGLE_QUOTED without 
        // specific JSON structure, we rely on the parser's ability to handle quoted strings.
        // In standard JSON, single quotes are not allowed, but if the reader is lenient:
        String json = "'789'";
        JsonReader reader = new JsonReader(new StringReader(json));
        reader.setLenient(true);
        assertEquals(789, reader.nextInt());
    }

    @Test
    public void testNextInt_FromPeekedDoubleQuoted() throws IOException {
        // Testing: p == PEEKED_DOUBLE_QUOTED
        String json = "\"101\"";
        JsonReader reader = new JsonReader(new StringReader(json));
        // Standard JSON allows strings, but nextInt() expects a number or a string that can be parsed
        assertEquals(101, reader.nextInt());
    }

    @Test
    public void testNextInt_FromPeekedDoubleQuoted_NotANumber() throws IOException {
        // Testing the catch (NumberFormatException ignored) branch inside quoted logic
        String json = "\"abc\"";
        JsonReader reader = new JsonReader(new StringReader(json));
        try {
            reader.nextInt();
            org.junit.Assert.fail("Expected NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testNextInt_IllegalStateException() throws IOException {
        // Testing the 'else' branch: throw new IllegalStateException
        // We use a boolean which is not an int
        String json = "true";
        JsonReader reader = new JsonReader(new StringReader(json));
        try {
            reader.nextInt();
            org.junit.Assert.fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            // Expected
        }
    }

    @Test
    public void testNextInt_PeekedNone() throws IOException {
        // Tests the initial check: if (p == PEEKED_NONE) { p = doPeek(); }
        String json = "99";
        JsonReader reader = new JsonReader(new StringReader(json));
        // Ensure peeked is NONE initially by just calling nextInt
        assertEquals(99, reader.nextInt());
    }
}
